// Prepare OpenRouter request for Gemini
const color = $input.item.json;

const prompt = `A modern kitchen with ${color.prompt} kitchen cabinets. The cabinets are clearly visible with the new color applied. Photorealistic, professional interior photography, high quality, same layout and lighting as reference.`;

return {
  color: color,
  prompt: prompt,
  apiRequest: {
    model: 'google/gemini-2.0-flash-exp:free',
    messages: [
      {
        role: 'user',
        content: [
          {
            type: 'text',
            text: prompt
          },
          {
            type: 'image_url',
            image_url: {
              url: color.kitchenImage
            }
          }
        ]
      }
    ],
    max_tokens: 4096
  }
};

// Extract generated image URL from OpenRouter response
const response = $input.item.json;
const color = $input.item.color;

// For Gemini image generation, we get base64 image data
// In production, we'd upload to storage and get URL

const imageData = response.choices?.[0]?.message?.content;

return {
  colorId: color.id,
  colorName: color.name,
  colorHex: color.hex,
  imageData: imageData,
  timestamp: new Date().toISOString()
};
